/**
 * Odoo Node - Version 2
 * Discriminator: resource=opportunity, operation=get
 */


interface Credentials {
  odooApiKeyApi: CredentialReference;
  odooApi: CredentialReference;
}

/** Get an activity */
export type OdooV2OpportunityGetParams = {
  resource: 'opportunity';
  operation: 'get';
  authentication?: 'odooApiKeyApi' | 'odooApi' | Expression<string>;
/**
 * Opportunity to retrieve
 * @searchListMethod searchOpportunities
 * @default {"mode":"list","value":""}
 */
    opportunityId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Options
 * @default {}
 */
    options?: {
    /** Choose from the list, or specify IDs using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
     * @loadOptionsMethod getOpportunityFields
     * @default []
     */
    fieldsList?: string[];
  };
};

export type OdooV2OpportunityGetOutput = {
  __last_update?: string;
  active?: boolean;
  id?: number;
  kanban_state?: string;
  lost_reason?: boolean;
  name?: string;
  order_ids?: Array<number>;
  priority?: string;
  sale_amount_total?: number;
  sale_order_count?: number;
  type?: string;
  website_message_ids?: Array<number>;
  won_status?: string;
  write_date?: string;
};

export type OdooV2OpportunityGetNode = {
  type: 'n8n-nodes-base.odoo';
  version: 2;
  config: NodeConfig<OdooV2OpportunityGetParams> & { credentials?: Credentials };
  output?: Items<OdooV2OpportunityGetOutput>;
};